CustomField.formula:
/*Year*/
If(Contains(LEFT( Presentation_Demo_Date_Time__c , 2), "/"), /*Month is 1 characters*/
  if(Contains(Right(Left(Presentation_Demo_Date_Time__c, 4), 2), "/"), /*Date is 1 char*/
    Right(Left(Presentation_Demo_Date_Time__c, 8), 4),
    Right(Left(Presentation_Demo_Date_Time__c, 9), 4)
  ),
  if(Contains(Right(Left(Presentation_Demo_Date_Time__c, 5), 2), "/"), /*Month is 2 chars and Date is 1 char*/
    Right(Left(Presentation_Demo_Date_Time__c, 9), 4),
    Right(Left(Presentation_Demo_Date_Time__c, 10), 4)
  )
)
&"-"&
/*Month*/
If(Contains(LEFT( Presentation_Demo_Date_Time__c , 2), "/"), /*Month is 1 characters*/
  LEFT( Presentation_Demo_Date_Time__c , 1),
  LEFT( Presentation_Demo_Date_Time__c , 2)
)
&"-"&
/*Day*/
If(Contains(LEFT( Presentation_Demo_Date_Time__c , 2), "/"), /*Month is "1/" characters*/
  if(Contains(Right(Left(Presentation_Demo_Date_Time__c, 4), 2), "/"), /*Date is 1 char*/
    Right(Left(Presentation_Demo_Date_Time__c, 3), 1),
    Right(Left(Presentation_Demo_Date_Time__c, 4), 2)
  ),
  if(Contains(Right(Left(Presentation_Demo_Date_Time__c, 5), 2), "/"), /*Date is 1 char*/
    Right(Left(Presentation_Demo_Date_Time__c, 4), 1),
    Right(Left(Presentation_Demo_Date_Time__c, 5), 2)
  )
)

/*
Possible Iterations
1/1/2023
